@startuml

class HospitalHouseMD {}

class Patient {
  + name : string
}

class Doctor {
  + name : string
}

class Diagnosis {
  + description : string
}

class Treatment {
  + name : string
}

class ConsentForm {
  + date : date
}

enum PriorityScore {
  High
  Low
}

enum TreatmentStage {
  Stage1
  Stage2
  Stage3
}

class Illness {
  + name : string
}

HospitalHouseMD "1" *-- "*" Patient
Patient "1" -- "*" Doctor
Doctor "1" -- "*" Diagnosis
Patient "1" -- "*" Treatment
Diagnosis "1" -- "*" Treatment
Diagnosis "1" -- "1" Illness
Illness "1" -- "1" PriorityScore
Treatment "1" -- "1" TreatmentStage
Patient "1" -- "0..*" ConsentForm
ConsentForm "1" -- "0..*" Treatment
Doctor "1" -- "*" Treatment

@enduml

